const raw = $input.first().json.stdout;
const summary = JSON.parse(raw);
if (summary.mode !== 'registry_driven_daily_enqueue') throw new Error('unexpected_daily_enqueue_mode');
if (!Array.isArray(summary.outcomes)) throw new Error('daily_outcomes_missing');
if (summary.considered !== summary.outcomes.length) throw new Error('daily_outcome_count_mismatch');
const terminal = new Set(['enqueued','duplicate','fail_closed']);
if (summary.outcomes.some((row) => !terminal.has(row.status))) throw new Error('daily_non_terminal_outcome');
return [{json:{...summary,publication_authorized:false,auto_publish:false}}];
